function harvest(){s.harvests++;let produced=0;s.tiles.forEach((t,i)=>{if(t==='sown'){s.grain++;produced++;s.tiles[i]='field'}else if(t==='vegsown'){s.vegetables++;produced++;s.tiles[i]='field'}});let foodNeed=s.workers*2;if(s.improvements.includes('Hearth')){let baked=Math.min(s.grain,2);s.grain-=baked;s.food+=baked*2;foodNeed=Math.max(0,foodNeed-baked*2)}let paid=Math.min(s.food,foodNeed);s.food-=paid;if(paid<foodNeed){let short=foodNeed-paid;s.begging+=short;addLog(`Harvest: ${produced} crop(s), but short ${short} food. Took a begging card.`)}else addLog(`Harvest: ${produced} crop(s) gathered, family fed (${foodNeed} food).`);s.sheep=Math.floor(s.sheep/2);s.boar=Math.floor(s.boar/2);s.cattle=Math.floor(s.cattle/2)}
function endRound(){if(s.freeWorkers>0){say('Place all your workers before ending the season.');return}if(s.round%2===0)harvest();s.round++;if(s.round>8){s.gameOver=true;showScore();return}s.freeWorkers=s.workers;s.used=[];s.familyGrown=false;let supply=2+Math.floor((s.round-1)/2);s.food+=s.round%2===1?1:0;addLog(`${season()} begins. A small food supply arrives.`);render();window.scrollTo({top:0,behavior:'smooth'})}
function showScore(){const scoreLines=[['Fields & pastures',s.fields+s.pastures],['Animals',s.sheep+s.boar*2+s.cattle*3],['Crops in storage',s.grain+s.vegetables],['Family',s.workers*3],['Rooms & improvements',(s.rooms-2)*2+s.improvements.length],['Begging cards',-s.begging*3]];const total=score();document.getElementById('scoreCard').innerHTML=`<div class="eyebrow">Eight seasons on the land</div><h2>Your harvest is in</h2><p>You built a life on the farm. Here's how your homestead grew.</p><div class="score-total">${total} <span style="font:14px system-ui;color:#758071">points</span></div>${scoreLines.map(x=>`<div class="score-line"><span>${x[0]}</span><strong>${x[1]>=0?'+':''}${x[1]}</strong></div>`).join('')}<button class="primary" id="restart">Start a new farm</button>`;document.getElementById('endScreen').classList.add('show');document.getElementById('restart').onclick=()=>{localStorage.removeItem('hearth-save');s=initial();document.getElementById('endScreen').classList.remove('show');render()}}
document.getElementById('actions').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)doAction(+b.dataset.action)});document.getElementById('farmBoard').addEventListener('click',e=>{const b=e.target.closest('[data-plot]');if(b)choosePlot(+b.dataset.plot)});document.getElementById('endRound').onclick=endRound;document.getElementById('upgrades').addEventListener('click',e=>{const b=e.target.closest('[data-upgrade]');if(b)upgrade(b.dataset.upgrade)});document.getElementById('cancelModal').onclick=()=>document.getElementById('overlay').classList.remove('show');document.getElementById('overlay').addEventListener('click',e=>{if(e.target.id==='overlay')e.currentTarget.classList.remove('show')});render();
</script>
</body>
</html>

case 4:openChoice('Bring animals home','Choose a pair to start a small flock or herd. Without a pasture, only one animal of a type can stay.',[['Sheep','🐑','sheep'],['Boar','🐗','boar'],['Cattle','🐄','cattle']].map(([n,ico,key])=>({title:`Take ${n.toLowerCase()}`,desc:`Gain 2 ${n.toLowerCase()}. Pasture lets you keep more.`,icon:ico,run:()=>{const cap=s.pastures?2+(s.improvements.includes('Stable')?2:0):1;const add=Math.min(2,Math.max(0,cap-s[key]));s[key]+=add;addLog(add?`Brought ${add} ${n.toLowerCase()} to the farm.`:`No room for more ${n.toLowerCase()}. Fence a pasture first.`)}})));break;case 5:if(s.wood<5||s.reed<2||!s.tiles.includes('empty')){s.freeWorkers++;s.used.pop();say('Need 5 wood, 2 reed, and an open plot.');return render()}s.wood-=5;s.reed-=2;s.rooms++;s.tiles[s.tiles.indexOf('empty')]='room';addLog('Built a new family room.');done();break;case 6:if(s.rooms<=s.workers||s.familyGrown){s.freeWorkers++;s.used.pop();say(s.familyGrown?'A family member already joined this season.':'Build a room before growing your family.');return render()}s.workers++;s.freeWorkers++;s.familyGrown=true;addLog('A new family member joined the homestead!');done();break;case 7:s.food+=3;addLog('Earned 3 food from day labor.');done();break}}
function plot(i){if(!s.freeWorkers){say('No workers available.');return}if(s.tiles[i]!=='empty'){say('Choose an open plot.');return}openChoice('Improve your farm','Use a worker to develop this open space.',[{title:'Plow a field',desc:'Makes a field ready for crops.',icon:'🌾',disabled:s.fields>=4,run:()=>{if(!consume(2))return;s.fields++;s.tiles[i]='field';addLog('Plowed a new field.')}},{title:'Fence a pasture',desc:'Costs 2 wood. Holds up to 2 animals.',icon:'🐑',disabled:s.wood<2,run:()=>{if(!consume(4))return;s.wood-=2;s.pastures++;s.tiles[i]='pasture';addLog('Fenced a pasture for the animals.')}},{title:'Build a room',desc:'Costs 5 wood and 2 reed. Room for a growing family.',icon:'🏠',disabled:s.wood<5||s.reed<2,run:()=>{if(!consume(5))return;s.wood-=5;s.reed-=2;s.rooms++;s.tiles[i]='room';addLog('Built a new family room.')}}])}
function upgrade(n){if(n==='Hearth'&&s.clay>=2&&!s.improvements.includes(n)){s.clay-=2;s.improvements.push(n);addLog('Built a hearth. Grain and vegetables now bake into food.')}if(n==='Stable'&&s.wood>=2&&!s.improvements.includes(n)){s.wood-=2;s.improvements.push(n);addLog('Built a stable. Pastures can hold more animals.')}render()}
function harvest(){let produced=0;s.tiles.forEach((t,i)=>{if(t==='sown'){s.grain+=2;produced+=2;s.tiles[i]='field'}else if(t==='vegsown'){s.vegetables+=2;produced+=2;s.tiles[i]='field'}});let need=s.workers*2;if(s.improvements.includes('Hearth')){const bake=Math.min(s.grain,2);s.grain-=bake;s.food+=bake*2;need=Math.max(0,need-bake*2)}const paid=Math.min(s.food,need);s.food-=paid;if(paid<need){s.begging+=need-paid;addLog(`Harvest gathered ${produced} crops; family short ${need-paid} food.`)}else addLog(`Harvest gathered ${produced} crops; family fed with ${need} food.`);s.sheep=Math.floor(s.sheep/2);s.boar=Math.floor(s.boar/2);s.cattle=Math.floor(s.cattle/2)}
function endRound(){if(s.freeWorkers){say('Place all your workers before ending the season.');return}if(s.round%2===0)harvest();if(s.round===8){showScore();s.gameOver=true;save();return}s.round++;s.freeWorkers=s.workers;s.used=[];s.familyGrown=false;s.food++;addLog(`${season()} begins. A small food supply arrives.`);render();window.scrollTo({top:0,behavior:'smooth'})}
function showScore(){const lines=[['Fields & pastures',s.fields+s.pastures],['Animals',s.sheep+s.boar*2+s.cattle*3],['Crops in storage',s.grain+s.vegetables],['Family',s.workers*3],['Rooms & improvements',(s.rooms-2)*2+s.improvements.length],['Begging cards',-s.begging*3]],total=score();document.getElementById('scoreCard').innerHTML=`<div class="eyebrow">Eight seasons on the land</div><h2>Your harvest is in</h2><p>You built a life on the farm. Here's how your homestead grew.</p><div class="score-total">${total} <span style="font:14px system-ui;color:#758071">points</span></div>${lines.map(x=>`<div class="score-line"><span>${x[0]}</span><strong>${x[1]>=0?'+':''}${x[1]}</strong></div>`).join('')}<button class="primary" id="restart">Start a new farm</button>`;document.getElementById('endScreen').classList.add('show');document.getElementById('restart').onclick=()=>{localStorage.removeItem('hearth-save');s=initial();document.getElementById('endScreen').classList.remove('show');render()}}
document.getElementById('actions').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)action(+b.dataset.action)});document.getElementById('farmBoard').addEventListener('click',e=>{const b=e.target.closest('[data-plot]');if(b)plot(+b.dataset.plot)});document.getElementById('endRound').onclick=endRound;document.getElementById('upgrades').addEventListener('click',e=>{const b=e.target.closest('[data-upgrade]');if(b)upgrade(b.dataset.upgrade)});document.getElementById('cancelModal').onclick=()=>document.getElementById('overlay').classList.remove('show');document.getElementById('overlay').addEventListener('click',e=>{if(e.target.id==='overlay')e.currentTarget.classList.remove('show')});render();
