const initial=()=>({round:1,workers:2,freeWorkers:2,wood:3,clay:2,reed:1,food:3,grain:1,vegetables:0,fields:0,pastures:0,sheep:0,boar:0,cattle:0,rooms:2,tiles:['room','room','empty','empty','empty','empty','empty','empty','empty'],familyGrown:false,used:[],improvements:[],begging:0,log:[],gameOver:false});let s;try{s=JSON.parse(localStorage.getItem('hearth-save'))||initial()}catch{s=initial()}
const names=['Gather wood','Clay & reed','Plow a field','Sow crops','Raise livestock','Build a room','Grow your family','Day labor'],icons=['🪵','🧱','⛏️','🌾','🐑','🏠','👶','🪙'],descriptions=['Collect 3 wood','Collect 2 clay + 1 reed','Prepare a fresh field','Plant grain or vegetables','Bring animals to your farm','Add a room for your family','Welcome another worker','Take 3 food'];
function save(){try{localStorage.setItem('hearth-save',JSON.stringify(s))}catch{}}function addLog(text){s.log.unshift({round:s.round,text});s.log=s.log.slice(0,12)}function say(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}function season(){return ['Spring','Summer','Autumn','Winter'][(s.round-1)%4]}function score(){return s.fields+s.pastures+s.sheep+s.boar*2+s.cattle*3+s.grain+s.vegetables+s.workers*3+(s.rooms-2)*2+s.improvements.length-s.begging*3}
function render(){if(s.gameOver)return;document.getElementById('seasonChip').textContent=['🌱','☀️','🍂','❄️'][(s.round-1)%4]+' '+season().toUpperCase();document.getElementById('roundTitle').textContent=`${season()} · Year ${Math.ceil(s.round/4)}`;document.getElementById('roundCopy').textContent=s.round%2===0?'The harvest is near. Make one last good choice for your farm.':'A fresh season begins. Place your family and make the most of the day.';document.getElementById('roundCount').textContent=`${s.round} / 8`;document.getElementById('workerCount').textContent=s.workers;
const resources=[['🍞','Food',s.food],['🪵','Wood',s.wood],['🧱','Clay',s.clay],['🪨','Reed',s.reed],['🌾','Grain',s.grain],['🥕','Veg',s.vegetables],['⭐','Points',score()]];document.getElementById('resources').innerHTML=resources.map(r=>`<div class="resource"><span class="res-icon">${r[0]}</span><div><span class="res-label">${r[1]}</span><span class="res-value">${r[2]}</span></div></div>`).join('');document.getElementById('farmBoard').innerHTML=s.tiles.map((t,i)=>{let [icon,label,sub]=['＋','Open plot','Tap to improve'];if(t==='room')[icon,label,sub]=['🏠','Family room','A warm home'];if(t==='field')[icon,label,sub]=['🌱','Field','Ready for seed'];if(t==='sown')[icon,label,sub]=['🌾','Sown field','Growing grain'];if(t==='vegsown')[icon,label,sub]=['🥕','Kitchen garden','Growing vegetables'];if(t==='pasture')[icon,label,sub]=['🐑','Pasture','Fenced grazing'];return `<button class="plot ${t}" data-plot="${i}" aria-label="${label}"><span class="tile-icon">${icon}</span><span class="tile-name">${label}</span><span class="tile-sub">${sub}</span></button>`}).join('');document.getElementById('farmMeta').textContent=`${s.rooms} rooms · ${s.fields} fields · ${s.pastures} pastures`;document.getElementById('animals').innerHTML=[['🐑','Sheep',s.sheep],['🐗','Boar',s.boar],['🐄','Cattle',s.cattle]].map(x=>`<div class="animal"><span>${x[0]} ${x[1]}</span><strong>${x[2]}</strong></div>`).join('');document.getElementById('workerText').textContent=s.freeWorkers?`${s.freeWorkers} family ${s.freeWorkers===1?'member':'members'} ready to work`:'All workers have found their work';document.getElementById('workerIcons').textContent='👩‍🌾 '.repeat(s.freeWorkers)+'· '.repeat(Math.max(0,s.workers-s.freeWorkers));document.getElementById('actionsLeft').textContent=`${s.freeWorkers} placement${s.freeWorkers===1?'':'s'} left`;
document.getElementById('actions').innerHTML=names.map((n,i)=>`<button class="action ${s.used.includes(i)?'used':''}" data-action="${i}" ${s.freeWorkers===0||s.used.includes(i)?'disabled':''}><span class="action-top"><span class="action-icon">${icons[i]}</span><span class="action-name">${n}</span></span><span class="action-desc">${descriptions[i]}</span></button>`).join('');document.getElementById('endRound').disabled=s.freeWorkers>0;renderUpgrades();document.getElementById('log').innerHTML=s.log.length?s.log.map(l=>`<div class="log-item"><span>Y${Math.ceil(l.round/4)} · ${['Sp','Su','Au','Wi'][(l.round-1)%4]}</span><span>${l.text}</span></div>`).join(''):'<div class="log-item">Your story on the land starts here.</div>';save()}
function renderUpgrades(){const defs=[['Hearth','🔥','Spend 2 clay','2 clay',()=>s.clay>=2&&!s.improvements.includes('Hearth')],['Stable','🛖','Spend 2 wood','2 wood',()=>s.wood>=2&&!s.improvements.includes('Stable')]];document.getElementById('upgrades').innerHTML=defs.map(([n,i,d,c,ok])=>`<div class="upgrade"><div class="upgrade-text"><strong>${i} ${n} ${s.improvements.includes(n)?'✓':''}</strong><span>${s.improvements.includes(n)?'Improvement complete':d}</span></div><button class="secondary" data-upgrade="${n}" ${ok()?'':'disabled'}>${s.improvements.includes(n)?'Built':c}</button></div>`).join('')}
function consume(i){if(s.freeWorkers<1||s.used.includes(i))return false;s.freeWorkers--;s.used.push(i);return true}function done(){render();if(!s.freeWorkers)say('All workers have finished for this season.')}function openChoice(title,copy,choices){document.getElementById('modalTitle').textContent=title;document.getElementById('modalCopy').textContent=copy;document.getElementById('choices').innerHTML=choices.map((c,i)=>`<button class="choice" data-choice="${i}" ${c.disabled?'disabled':''}><span><strong>${c.title}</strong><small>${c.desc}</small></span><span>${c.icon||'›'}</span></button>`).join('');document.getElementById('overlay').classList.add('show');document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{const c=choices[+b.dataset.choice];if(c.run){c.run();document.getElementById('overlay').classList.remove('show');done()}})}

function action(i){if(!consume(i))return;switch(i){case 0:s.wood+=3;addLog('Gathered 3 wood from the forest.');done();break;case 1:s.clay+=2;s.reed++;addLog('Collected 2 clay and 1 reed.');done();break;case 2:if(s.fields>=4){s.freeWorkers++;s.used.pop();say('Your farm has room for 4 fields.');return render()}s.fields++;s.tiles[s.tiles.indexOf('empty')]='field';addLog('Plowed a new field.');done();break;case 3:if(!s.tiles.includes('field')){s.freeWorkers++;s.used.pop();say('Plow a field before you sow.');return render()}openChoice('Sow your seeds','Choose a crop to plant in one of your empty fields.',[{title:'Plant grain',desc:'Spend 1 grain. Harvest 2 grain at the next harvest.',icon:'🌾',disabled:s.grain<1,run:()=>{s.grain--;s.tiles[s.tiles.indexOf('field')]='sown';addLog('Sowed a field with grain.')}},{title:'Plant vegetables',desc:'Spend 1 vegetable. Harvest 2 vegetables next harvest.',icon:'🥕',disabled:s.vegetables<1,run:()=>{s.vegetables--;s.tiles[s.tiles.indexOf('field')]='vegsown';addLog('Planted a kitchen garden.')}}]);break;
case 4:openChoice('Bring animals home','Choose an animal to start a small flock or herd. Without a pasture, only one animal of a type can stay.',[['Sheep','🐑','sheep'],['Boar','🐗','boar'],['Cattle','🐄','cattle']].map(([n,ico,key])=>({title:`Take ${n.toLowerCase()}`,desc:`Gain 2 ${n.toLowerCase()}. Pasture lets you keep more.`,icon:ico,run:()=>{const cap=s.pastures?2+(s.improvements.includes('Stable')?2:0):1,add=Math.min(2,Math.max(0,cap-s[key]));s[key]+=add;addLog(add?`Brought ${add} ${n.toLowerCase()} to the farm.`:`No room for more ${n.toLowerCase()}. Fence a pasture first.`)}})));break;
case 5:if(s.wood<5||s.reed<2||!s.tiles.includes('empty')){s.freeWorkers++;s.used.pop();say('Need 5 wood, 2 reed, and an open plot.');return render()}s.wood-=5;s.reed-=2;s.rooms++;s.tiles[s.tiles.indexOf('empty')]='room';addLog('Built a new family room.');done();break;case 6:if(s.rooms<=s.workers||s.familyGrown){s.freeWorkers++;s.used.pop();say(s.familyGrown?'A family member already joined this season.':'Build a room before growing your family.');return render()}s.workers++;s.freeWorkers++;s.familyGrown=true;addLog('A new family member joined the homestead!');done();break;case 7:s.food+=3;addLog('Earned 3 food from day labor.');done();break}}
function plot(i){if(!s.freeWorkers){say('No workers available.');return}if(s.tiles[i]!=='empty'){say('Choose an open plot.');return}openChoice('Improve your farm','Use a worker to develop this open space.',[{title:'Plow a field',desc:'Makes a field ready for crops.',icon:'🌾',disabled:s.fields>=4,run:()=>{if(!consume(2))return;s.fields++;s.tiles[i]='field';addLog('Plowed a new field.')}},{title:'Fence a pasture',desc:'Costs 2 wood. Holds up to 2 animals.',icon:'🐑',disabled:s.wood<2,run:()=>{if(!consume(4))return;s.wood-=2;s.pastures++;s.tiles[i]='pasture';addLog('Fenced a pasture for the animals.')}},{title:'Build a room',desc:'Costs 5 wood and 2 reed. Room for a growing family.',icon:'🏠',disabled:s.wood<5||s.reed<2,run:()=>{if(!consume(5))return;s.wood-=5;s.reed-=2;s.rooms++;s.tiles[i]='room';addLog('Built a new family room.')}}])}
