 </style></head><body><div class="app"><header class="topbar"><div class="brand"><div class="brand-mark">🌱</div><div><h1>Hearth &amp; Harvest</h1><p>A little life on the land</p></div></div><div class="season-chip" id="seasonChip"></div></header>
 <section class="hero"><div><h2 class="round-title" id="roundTitle"></h2><p class="round-copy" id="roundCopy"></p></div><div class="round-stat"><div class="stat-pill"><b id="workerCount"></b><span>Workers</span></div><div class="stat-pill"><b id="roundCount"></b><span>Season</span></div></div></section><div class="resource-strip" id="resources"></div><main class="layout"><section class="panel"><div class="panel-head"><div><div class="eyebrow">Your homestead</div><h2>Farmstead</h2></div><div class="farm-meta" id="farmMeta"></div></div><div class="farm-board" id="farmBoard"></div><div class="farm-legend"><span><i class="legend-dot" style="background:#bd9955"></i>Fields</span><span><i class="legend-dot" style="background:#c9d6ad"></i>Pasture</span><span><i class="legend-dot" style="background:#a7744c"></i>Home</span></div><div class="animals-row" id="animals"></div><div class="worker-status"><span id="workerText"></span><span class="worker-icons" id="workerIcons"></span></div></section><div class="right-col"><section class="panel"><div class="panel-head"><div><div class="eyebrow">Choose wisely</div><h2>Today's work</h2></div><span class="farm-meta" id="actionsLeft"></span></div><div class="actions-grid" id="actions"></div><div class="action-panel-foot"><div class="hint">Every action space can be used once per season.<br>Harvest comes at the end of every other season.</div><button class="primary" id="endRound">End season →</button></div></section><section class="panel"><div class="panel-head"><div><div class="eyebrow">A better homestead</div><h2>Improvements</h2></div><span class="farm-meta">once each</span></div><div class="upgrades" id="upgrades"></div></section><section class="panel"><div class="panel-head"><div><div class="eyebrow">From the fields</div><h2>Season notes</h2></div></div><div class="log" id="log"></div></section></div></main><p class="small-note">Build a thriving farm, feed your family, and make every plot count.</p></div><div class="overlay" id="overlay"><div class="modal"><h2 id="modalTitle"></h2><p id="modalCopy"></p><div class="choices" id="choices"></div><div class="close-row"><button class="secondary" id="cancelModal">Not now</button></div></div></div><div class="end-screen" id="endScreen"><div class="score-card" id="scoreCard"></div></div><div class="toast" id="toast"></div><script>
+(() => {
