+      const crop=game.sown[i]?' · '+game.sown[i]:'';
+      return `<button class="plot ${type}" data-plot="${i}" aria-label="Plot ${i+1}: ${data[1]}${crop}"><span class="tile-icon">${data[0]}</span><span class="tile-name">${data[1]}</span><span class="tile-sub">${data[2]}</span></button>`;
+    }).join('');
+    const animals=['sheep','cattle','pigs']; $('animals').innerHTML=animals.map((a,i)=>`<div class="animal"><span>${icons[6+i]} ${a[0].toUpperCase()+a.slice(1)}</span><strong>${game.resources[a]}</strong></div>`).join('');
+    $('farmMeta').textContent=`${game.board.filter(Boolean).length} / 9 plots`;
+    $('workerText').textContent=`Family at home · ${game.workers} worker${game.workers===1?'':'s'} ready`;
+    $('workerIcons').textContent='👩‍🌾 '.repeat(game.workers);
+    $('actionsLeft').textContent=`${game.used.length} / ${game.workers} placed`;
