+    $('endRound').disabled=game.gameOver||game.used.length<game.workers;
+    $('upgrades').innerHTML=upgrades.map(u=>`<div class="upgrade"><div class="upgrade-text"><strong>${u.name}${game.bought.includes(u.id)?' ✓':''}</strong><span>${u.desc}</span></div><button class="secondary" data-upgrade="${u.id}" ${game.gameOver||game.bought.includes(u.id)||!canPay(u.cost)?'disabled':''}>${game.bought.includes(u.id)?'Owned':'Build'}</button></div>`).join('');
+    $('log').innerHTML=game.log.map((x,i)=>`<div class="log-item"><b>${i===0?'NOW':'•'}</b><span>${esc(x)}</span></div>`).join('');
+    $('endScreen').classList.toggle('show',game.gameOver);
+    save();
+  }
+  function modal(title,copy,choices){
+    $('modalTitle').textContent=title; $('modalCopy').textContent=copy;
+    $('choices').innerHTML=choices.map((c,i)=>`<button class="choice" data-choice="${i}" ${c.disabled?'disabled':''}><span><strong>${c.title}</strong><small>${c.detail||''}</small></span><b>${c.icon||'→'}</b></button>`).join('');
+    $('overlay').classList.add('show');
+  }
