+      modal(id==='field'?'Plow a field':'Build a pasture',id==='field'?'Choose an open plot to prepare for sowing.':'Choose an open plot; fencing costs 2 wood.',free.map(i=>({title:`Plot ${i+1}`,detail:'Open ground',icon:'＋'})));
