  function harvest(){
    let cropFood=0, cropGrain=0, cropVeg=0;
    for(const [index,crop] of Object.entries(game.sown)){
      if(crop==='grain'){cropGrain+=2;cropFood+=1;} else {cropVeg+=1;}
      game.board[+index]='field';
    }
    game.sown={}; game.resources.grain+=cropGrain; game.resources.vegetables+=cropVeg;
    if(game.bought.includes('garden'))game.resources.vegetables++;
    if(game.bought.includes('hearth'))cropFood++;
    game.resources.food+=cropFood;
    const need=game.workers, paid=Math.min(need,game.resources.food);game.resources.food-=paid;
    const short=need-paid;
    if(short)game.score-=short*3;
    note(`Harvest: ${cropGrain} grain, ${cropVeg+(game.bought.includes('garden')?1:0)} vegetables; ${paid}/${need} meals served${short?` (−${short*3} points)`:''}.`);
  }
  function endSeason(){
    if(game.used.length<game.workers||game.gameOver)return;
    if((game.season+1)%2===0)harvest();
    game.season++;
    if(game.season>=seasons.length){
      game.gameOver=true;
      const land=game.board.filter(Boolean).length;
      const animals=game.resources.sheep+game.resources.cattle*2+game.resources.pigs;
      game.score+=land+game.workers*3+animals+Math.floor(game.resources.food/2)+game.resources.grain+game.resources.vegetables*2+game.bought.length*2;
      note('The final winter settles over your thriving homestead.');
      renderScore();
    } else {
      game.used=[];
      note(`${seasons[game.season]} begins. Your workers are ready for a new day.`);
    }
    render();
  }
  function renderScore(){
    const land=game.board.filter(Boolean).length;
